Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cmath>
#include <iostream>
using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int main() {
    int x, y, n;
    cin >> x >> y >> n;

    int d = gcd(x, y);
    x /= d;
    y /= d;

    if (n >= y) {
        cout << x << "/" << y << "\n";
    } else {
        long double target = (long double)x / y;
        long double bestError = target;
        int bestNum = 0;
        int bestDen = 1;
        int i = 1;

        while (i <= n) {
            long double scaled = i * target;
            long double t = floor(scaled);
            long double err1 = std::abs(t / i - target);
            long double err2 = std::abs((t + 1) / i - target);

            if (bestError > err1 || bestError > err2) {
                if (err1 > err2) {
                    bestNum = (int)t + 1;
                    bestDen = i;
                    bestError = err2;
                } else {
                    bestNum = (int)t;
                    bestDen = i;
                    bestError = err1;
                }
            }
            ++i;
        }

        cout << bestNum << "/" << bestDen;
    }

    return 0;
}
